use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // RecordSeen: mark every considered item id as seen in the
        // read-write 'seen' store. `recorded` counts the ids that were
        // not already present, so repeated runs over the same ids do not
        // inflate the count. Being a u32, `recorded >= 0` holds by type.
        let mut recorded: u32 = 0;

        for id in &published.considered {
            if state_rw::get(id).is_none() {
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
